import math
import random

import pytest

from var import historical_var, parametric_var, inv_normal_cdf


def _normal_returns(n, mu=0.0, sigma=0.01, seed=12345):
    rng = random.Random(seed)
    out = []
    while len(out) < n:
        u1 = rng.random()
        u2 = rng.random()
        if u1 == 0.0:
            continue
        mag = sigma * math.sqrt(-2.0 * math.log(u1))
        out.append(mu + mag * math.cos(2 * math.pi * u2))
        if len(out) < n:
            out.append(mu + mag * math.sin(2 * math.pi * u2))
    return out


TRUE_VAR95 = 1.6449 * 0.01


class TestInverseCDF:
    def test_invcdf_95(self):
        assert round(inv_normal_cdf(0.95), 3) == 1.645

    def test_invcdf_symmetry(self):
        assert abs(inv_normal_cdf(0.05) + inv_normal_cdf(0.95)) < 1e-8

    def test_invcdf_monotone(self):
        ps = [0.01, 0.25, 0.5, 0.75, 0.99]
        zs = [inv_normal_cdf(p) for p in ps]
        assert zs == sorted(zs)

    def test_invcdf_median_zero(self):
        assert abs(inv_normal_cdf(0.5)) < 1e-12

    def test_invcdf_99(self):
        assert abs(inv_normal_cdf(0.99) - 2.3263) < 1e-4


class TestParametricVar:
    def test_within_2pct_of_true(self):
        rets = _normal_returns(100_000)
        v = parametric_var(rets, 0.95)
        assert abs(v - TRUE_VAR95) / TRUE_VAR95 < 0.02

    def test_alpha_ordering(self):
        rets = _normal_returns(100_000)
        assert parametric_var(rets, 0.99) > parametric_var(rets, 0.95)


class TestHistoricalVar:
    def test_within_3pct_of_true(self):
        rets = _normal_returns(100_000)
        v = historical_var(rets, 0.95)
        assert abs(v - TRUE_VAR95) / TRUE_VAR95 < 0.03

    def test_alpha_ordering(self):
        rets = _normal_returns(100_000)
        assert historical_var(rets, 0.99) > historical_var(rets, 0.95)

    def test_convergence(self):
        true_gap_small = []
        true_gap_large = []
        for seed in range(20):
            big = historical_var(_normal_returns(100_000, seed=1000 + seed))
            small = historical_var(_normal_returns(1_000, seed=1000 + seed))
            true_gap_large.append(abs(big - TRUE_VAR95))
            true_gap_small.append(abs(small - TRUE_VAR95))
        assert sum(true_gap_large) / len(true_gap_large) < sum(
            true_gap_small
        ) / len(true_gap_small)


class TestEdgeCases:
    def test_all_positive_constant_returns(self):
        rets = [0.001] * 1000
        assert historical_var(rets, 0.95) < 0
        assert parametric_var(rets, 0.95) < 0

    def test_invalid_alpha(self):
        with pytest.raises(ValueError):
            historical_var([0.01], 0.0)
        with pytest.raises(ValueError):
            parametric_var([0.01], 1.0)

    def test_empty_returns(self):
        with pytest.raises(ValueError):
            historical_var([], 0.95)
        with pytest.raises(ValueError):
            parametric_var([], 0.95)

